import subprocess, sys, os
ENVBASE = dict(PATH="/usr/bin:/bin", HOME="/tmp/rg/io/emptyhome",
               GOPATH="/tmp/rg/io/emptyhome", GOROOT="/tmp/rg/io/emptyhome",
               RICHGO_LOCAL="1")
def run(data, color=True, args=("testfilter",), cwd="/tmp/rg/io/scratch", extraenv=None, timeout=20):
    env = dict(ENVBASE)
    if color: env["RICHGO_FORCE_COLOR"]="1"
    if extraenv: env.update(extraenv)
    p = subprocess.run(["/workspace/executable"]+list(args), input=data,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, cwd=cwd, timeout=timeout)
    return p
def esc(b):
    out=[]
    for ch in b:
        c=bytes([ch])
        if c==b'\x1b': out.append('\\x1b')
        elif c==b'\n': out.append('\\n')
        elif c==b'\r': out.append('\\r')
        elif c==b'\t': out.append('\\t')
        elif c==b'\x00': out.append('\\x00')
        elif 32<=ch<127: out.append(c.decode())
        else: out.append('\\x%02x'%ch)
    return ''.join(out)
